CREATE TABLE IF NOT EXISTS school_nodes(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('branch','campus')),name TEXT NOT NULL,parent_id TEXT REFERENCES school_nodes(id),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE IF NOT EXISTS class_campuses(class_id TEXT PRIMARY KEY REFERENCES academics(id),campus_id TEXT NOT NULL REFERENCES school_nodes(id));
CREATE TABLE IF NOT EXISTS section_subjects(section_id TEXT NOT NULL REFERENCES academics(id),subject_id TEXT NOT NULL REFERENCES academics(id),PRIMARY KEY(section_id,subject_id));
CREATE TABLE IF NOT EXISTS parent_sections(parent_id TEXT NOT NULL REFERENCES users(id),section_id TEXT NOT NULL REFERENCES academics(id),child_name TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),PRIMARY KEY(parent_id,section_id));
CREATE TABLE IF NOT EXISTS role_capabilities(role TEXT PRIMARY KEY,grants TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_capabilities(user_id TEXT PRIMARY KEY REFERENCES users(id),allows TEXT NOT NULL,denies TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS school_diaries(id TEXT PRIMARY KEY,teacher_id TEXT NOT NULL REFERENCES users(id),head_id TEXT NOT NULL REFERENCES users(id),section_id TEXT NOT NULL REFERENCES academics(id),diary_date TEXT NOT NULL,language TEXT NOT NULL CHECK(language IN('en','ur')),status TEXT NOT NULL CHECK(status IN('draft','submitted','under_review','returned','resubmitted','approved')),version INTEGER NOT NULL DEFAULT 1,content TEXT NOT NULL,snapshot TEXT NOT NULL,quote_payload TEXT NOT NULL,remarks TEXT NOT NULL DEFAULT '',submitted_at TEXT,reviewed_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(teacher_id,section_id,diary_date));
CREATE TABLE IF NOT EXISTS school_diary_versions(id TEXT PRIMARY KEY,diary_id TEXT NOT NULL REFERENCES school_diaries(id),version INTEGER NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL,remarks TEXT NOT NULL,snapshot TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(diary_id,version));
CREATE TABLE IF NOT EXISTS push_subscriptions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),endpoint TEXT NOT NULL UNIQUE,p256dh TEXT NOT NULL,auth TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS push_preferences(user_id TEXT PRIMARY KEY REFERENCES users(id),enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)));
CREATE TABLE IF NOT EXISTS push_deliveries(notification_id TEXT NOT NULL REFERENCES notifications(id),subscription_id TEXT NOT NULL REFERENCES push_subscriptions(id),status TEXT NOT NULL CHECK(status IN('pending','sending','sent','failed','expired')),attempts INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL,error_code TEXT,PRIMARY KEY(notification_id,subscription_id));
CREATE INDEX IF NOT EXISTS school_diaries_section_date ON school_diaries(section_id,diary_date,status);
CREATE INDEX IF NOT EXISTS school_diaries_reviewer ON school_diaries(head_id,status);
CREATE INDEX IF NOT EXISTS school_diaries_teacher ON school_diaries(teacher_id,diary_date);
CREATE TRIGGER IF NOT EXISTS school_versions_no_update BEFORE UPDATE ON school_diary_versions BEGIN SELECT RAISE(ABORT,'Diary history is append-only'); END;
CREATE TRIGGER IF NOT EXISTS school_versions_no_delete BEFORE DELETE ON school_diary_versions BEGIN SELECT RAISE(ABORT,'Diary history is append-only'); END;
INSERT OR IGNORE INTO migrations VALUES(4,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
CREATE TABLE IF NOT EXISTS subject_priorities(subject_id TEXT PRIMARY KEY REFERENCES academics(id) ON DELETE CASCADE,priority INTEGER NOT NULL DEFAULT 0 CHECK(priority BETWEEN 0 AND 1000000));

CREATE TABLE IF NOT EXISTS account_security(user_id TEXT PRIMARY KEY REFERENCES users(id),must_change_password INTEGER NOT NULL DEFAULT 0 CHECK(must_change_password IN(0,1)),password_enc TEXT,totp_secret TEXT,pending_secret TEXT,pending_until TEXT,last_counter INTEGER NOT NULL DEFAULT -1,recovery_hashes TEXT NOT NULL DEFAULT '[]',attempts INTEGER NOT NULL DEFAULT 0,window_start INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS branding_assets(id TEXT PRIMARY KEY,data TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS branding_assets_no_update BEFORE UPDATE ON branding_assets BEGIN SELECT RAISE(ABORT,'Branding is immutable'); END;
CREATE TRIGGER IF NOT EXISTS branding_assets_no_delete BEFORE DELETE ON branding_assets BEGIN SELECT RAISE(ABORT,'Branding is immutable'); END;
CREATE INDEX IF NOT EXISTS audit_action_time ON audit(action,created_at);
CREATE INDEX IF NOT EXISTS audit_created_time ON audit(created_at,id);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);

-- Reject new duplicate business keys while preserving any preexisting conflicting rows.
CREATE TRIGGER IF NOT EXISTS assignments_business_insert BEFORE INSERT ON assignments WHEN NEW.active=1 AND EXISTS(SELECT 1 FROM assignments old WHERE old.active=1 AND old.id<>NEW.id AND old.teacher_id=NEW.teacher_id AND old.section_id=NEW.section_id AND old.subject_id=NEW.subject_id AND old.session_id=NEW.session_id) BEGIN SELECT RAISE(ABORT,'This teaching assignment already exists.'); END;
CREATE TRIGGER IF NOT EXISTS assignments_business_update BEFORE UPDATE ON assignments WHEN NEW.active=1 AND EXISTS(SELECT 1 FROM assignments old WHERE old.active=1 AND old.id<>NEW.id AND old.teacher_id=NEW.teacher_id AND old.section_id=NEW.section_id AND old.subject_id=NEW.subject_id AND old.session_id=NEW.session_id) BEGIN SELECT RAISE(ABORT,'This teaching assignment already exists.'); END;
CREATE TRIGGER IF NOT EXISTS academics_business_insert BEFORE INSERT ON academics WHEN NEW.active=1 AND (NEW.kind='subject' OR NEW.kind='section') AND EXISTS(SELECT 1 FROM academics old WHERE old.id<>NEW.id AND old.active=1 AND old.kind=NEW.kind AND LOWER(TRIM(old.name))=LOWER(TRIM(NEW.name)) AND (NEW.kind='subject' OR old.parent_id=NEW.parent_id)) BEGIN SELECT RAISE(ABORT,'This academic record already exists.'); END;
CREATE TRIGGER IF NOT EXISTS academics_business_update BEFORE UPDATE ON academics WHEN NEW.active=1 AND (NEW.kind='subject' OR NEW.kind='section') AND EXISTS(SELECT 1 FROM academics old WHERE old.id<>NEW.id AND old.active=1 AND old.kind=NEW.kind AND LOWER(TRIM(old.name))=LOWER(TRIM(NEW.name)) AND (NEW.kind='subject' OR old.parent_id=NEW.parent_id)) BEGIN SELECT RAISE(ABORT,'This academic record already exists.'); END;
CREATE TRIGGER IF NOT EXISTS class_campuses_business_insert BEFORE INSERT ON class_campuses WHEN EXISTS(SELECT 1 FROM academics candidate JOIN class_campuses cc ON cc.campus_id=NEW.campus_id JOIN academics old ON old.id=cc.class_id WHERE candidate.id=NEW.class_id AND candidate.active=1 AND old.active=1 AND old.id<>candidate.id AND LOWER(TRIM(old.name))=LOWER(TRIM(candidate.name))) BEGIN SELECT RAISE(ABORT,'This class and section are already assigned to this campus.'); END;
CREATE TRIGGER IF NOT EXISTS class_campuses_business_update BEFORE UPDATE ON class_campuses WHEN EXISTS(SELECT 1 FROM academics candidate JOIN class_campuses cc ON cc.campus_id=NEW.campus_id JOIN academics old ON old.id=cc.class_id WHERE candidate.id=NEW.class_id AND candidate.active=1 AND old.active=1 AND old.id<>candidate.id AND LOWER(TRIM(old.name))=LOWER(TRIM(candidate.name))) BEGIN SELECT RAISE(ABORT,'This class and section are already assigned to this campus.'); END;
CREATE TRIGGER IF NOT EXISTS class_name_update_guard BEFORE UPDATE ON academics WHEN NEW.kind='class' AND NEW.active=1 AND EXISTS(SELECT 1 FROM class_campuses own JOIN class_campuses cc ON cc.campus_id=own.campus_id JOIN academics old ON old.id=cc.class_id WHERE own.class_id=NEW.id AND old.id<>NEW.id AND old.active=1 AND LOWER(TRIM(old.name))=LOWER(TRIM(NEW.name))) BEGIN SELECT RAISE(ABORT,'This class and section are already assigned to this campus.'); END;
INSERT OR IGNORE INTO migrations VALUES(6,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
